/**
 * Pre-encoded Annex-B placeholder keyframes for both H.264 and H.265.
 * Single 1280×720 black frame with a centred text label
 * ("RECONNECTING", "SLEEPING", …), encoded with x264/x265 ultrafast.
 * Embedded as base64 to avoid spawning ffmpeg at runtime.
 *
 * Frames carry SPS+PPS+IDR (H.264) or VPS+SPS+PPS+IDR (H.265) in a
 * single Annex-B blob so a fresh consumer (RTSP restream, WebRTC
 * AnnexB feed) decodes them without waiting for the next "real"
 * keyframe.
 *
 * Codec selection happens at the broker level: a broker carrying an
 * H.265 source emits H.265 placeholders so a WebRTC session
 * negotiated for H.265 sees correctly-coded fill while waking up.
 *
 * To regenerate (regression/refresh after font change):
 *   for label in reconnecting sleeping offline disabled waking; do
 *     upper=$(echo $label | tr '[:lower:]' '[:upper:]')
 *     # H.264
 *     ffmpeg -hide_banner -loglevel error -y -f lavfi \
 *       -i "color=c=0x101010:s=1280x720:r=1:d=1" \
 *       -vf "drawtext=fontfile=/System/Library/Fonts/Supplemental/Arial.ttf:text='${upper}':fontsize=64:fontcolor=0xb8b8b8:x=(w-text_w)/2:y=(h-text_h)/2" \
 *       -frames:v 1 -c:v libx264 -preset ultrafast -tune stillimage \
 *       -profile:v baseline -x264-params "nal-hrd=none:aud=0:repeat-headers=1" \
 *       -f h264 -bsf:v "h264_mp4toannexb,filter_units=remove_types=6" \
 *       ${label}.h264
 *     # H.265
 *     ffmpeg -hide_banner -loglevel error -y -f lavfi \
 *       -i "color=c=0x101010:s=1280x720:r=1:d=1" \
 *       -vf "drawtext=fontfile=/System/Library/Fonts/Supplemental/Arial.ttf:text='${upper}':fontsize=64:fontcolor=0xb8b8b8:x=(w-text_w)/2:y=(h-text_h)/2" \
 *       -frames:v 1 -c:v libx265 -preset ultrafast \
 *       -x265-params "keyint=1:repeat-headers=1" \
 *       -f hevc ${label}.h265
 *   done
 */

/**
 * State the broker is currently in. Drives which placeholder frame is
 * emitted to encoded subscribers (RTSP restream, WebRTC AnnexB feed)
 * while no live RTP is flowing. Default `reconnecting` is the
 * legacy behaviour for the dial-fail/reconnect path.
 */
export type PlaceholderKind = 'reconnecting' | 'sleeping' | 'offline' | 'disabled' | 'waking'

/**
 * Codec the placeholder frame is encoded as. Selection lives at the
 * broker level — an H.265 source surfaces H.265 placeholders so a
 * negotiated WebRTC session decodes them with the same codec as the
 * live stream. Only `'h264'` and `'h265'` are supported (the only
 * codecs that flow through the broker's encoded subscribers today).
 */
export type PlaceholderCodec = 'h264' | 'h265'

const FRAME_B64: Readonly<Record<PlaceholderCodec, Readonly<Record<PlaceholderKind, string>>>> = {
  h264: {
    reconnecting:
      '',
    sleeping:
      '',
    offline:
      '',
    disabled:
      '',
    waking:
      '',
  },
  h265: {
    reconnecting:
      '',
    sleeping:
      '',
    offline:
      '',
    disabled:
      '',
    waking:
      '',
  },
}

const cache: Partial<Record<PlaceholderCodec, Partial<Record<PlaceholderKind, Buffer>>>> = {}

/**
 * Get the pre-encoded placeholder frame for `(kind, codec)`. Buffer
 * is created once on first use per (codec, kind) pair and cached
 * permanently — safe to call from hot paths (~5-9KB per pair, ~60KB
 * worst-case across both codecs and all five states).
 */
export function getPlaceholderFrame(kind: PlaceholderKind, codec: PlaceholderCodec): Buffer {
  const codecCache = cache[codec] ?? (cache[codec] = {})
  const cached = codecCache[kind]
  if (cached) return cached
  const buf = Buffer.from(FRAME_B64[codec][kind], 'base64')
  codecCache[kind] = buf
  return buf
}

/**
 * Backwards-compatible alias for the legacy single-frame API. Returns
 * the H.264 `reconnecting` placeholder (the original "black screen
 * during reconnect" frame).
 *
 * @deprecated prefer `getPlaceholderFrame(kind, codec)` so the
 * consumer surfaces both the actual broker state and the matching
 * codec to the operator.
 */
export function getBlackPlaceholderFrame(): Buffer {
  return getPlaceholderFrame('reconnecting', 'h264')
}
